bool stratum_init(struct pool *pool) {
    json_t *req, *resp;
    bool retry = false;

    if (!stratum_connect(pool)) {
        applog(LOG_ERR, "Failed to connect to Stratum pool %s:%d", pool->rpc_url, pool->rpc_port);
        return false;
    }

    while (1) {
        req = json_object();
        if (!req)
            return false;

        json_object_set_new(req, "id", json_integer(1));
        json_object_set_new(req, "method", json_string("mining.subscribe"));
        json_object_set_new(req, "params", json_array());

        if (!stratum_send(pool, req)) {
            json_decref(req);
            return false;
        }

        resp = stratum_recv(pool);
        if (!resp) {
            json_decref(req);
            return false;
        }

        json_t *error = json_object_get(resp, "error");
        if (error) {
            const char *error_msg = json_string_value(json_array_get(error, 1));
            applog(LOG_ERR, "Stratum subscribe error: %s", error_msg);
            json_decref(req);
            json_decref(resp);
            return false;
        }

        json_t *result = json_object_get(resp, "result");
        if (!result || !json_is_array(result)) {
            applog(LOG_ERR, "Invalid Stratum subscribe response");
            json_decref(req);
            json_decref(resp);
            return false;
        }

        pool->session_id = strdup(json_string_value(json_array_get(result, 1)));
        pool->extranonce = strdup(json_string_value(json_array_get(result, 2)));

        json_decref(req);
        json_decref(resp);

        if (retry)
            break;

        retry = true;
    }

    return true;
}

bool init_stratum_session(struct pool *pool) {
    json_t *subscription_req, *resp;
    char *subscription_id, *session_id, *nonce;
    int retry = 0;

    while (1) {
        subscription_req = create_subscription_request(pool, retry ? NULL : pool->session_id);
        if (!subscription_req) {
            applog(LOG_ERR, "Failed to create subscription request for pool %s", pool->url);
            return false;
        }

        if (!send_stratum_request(pool, subscription_req)) {
            applog(LOG_ERR, "Failed to send subscription request to pool %s", pool->url);
            json_free(subscription_req);
            return false;
        }

        resp = receive_stratum_response(pool);
        if (!resp) {
            applog(LOG_ERR, "Failed to receive response from pool %s", pool->url);
            json_free(subscription_req);
            return false;
        }

        if (check_stratum_response_error(resp)) {
            applog(LOG_ERR, "Error in Stratum response from pool %s", pool->url);
            json_free(subscription_req);
            json_free(resp);
            return false;
        }

        subscription_id = extract_subscription_id(resp);
        session_id = extract_session_id(resp);
        nonce = extract_nonce(resp);

        if (!subscription_id || !session_id || !nonce) {
            applog(LOG_ERR, "Failed to extract necessary session data from Stratum response");
            json_free(subscription_req);
            json_free(resp);
            return false;
        }

        free(pool->session_id);
        pool->session_id = strdup(session_id);
        free(pool->nonce);
        pool->nonce = strdup(nonce);

        json_free(subscription_req);
        json_free(resp);

        if (retry) {
            retry = 0;
        }

        applog(LOG_INFO, "Stratum session initialized successfully for pool %s", pool->url);
        return true;
    }
}

bool stratum_init(struct pool *pool) {
    json_t *req, *resp;
    char *sid = NULL;
    int retry = 0;
    bool ret = false;

    do {
        req = json_object();
        if (!req)
            goto out;

        json_object_set_new(req, "id", json_integer(1));
        json_object_set_new(req, "method", json_string("mining.subscribe"));
        json_object_set_new(req, "params", json_array());

        if (!stratum_send_recv(pool, req, &resp)) {
            applog(LOG_WARNING, "Stratum subscribe failed for %s", pool->rpc_url);
            goto out;
        }

        if (!json_is_array(resp)) {
            applog(LOG_DEBUG, "Stratum subscribe response is not an array");
            goto out;
        }

        size_t idx;
        json_t *val;
        json_array_foreach(resp, idx, val) {
            if (idx == 0 && json_is_string(val))
                sid = strdup(json_string_value(val));
            else if (idx == 1 && json_is_string(val)) {
                char *nonce = strdup(json_string_value(val));
                if (nonce) {
                    free(pool->session_id);
                    pool->session_id = sid;
                    free(pool->nonce);
                    pool->nonce = nonce;
                }
            }
        }

        if (!sid) {
            applog(LOG_DEBUG, "Stratum subscribe response missing session ID");
            goto out;
        }

        ret = true;
    } while (0);

out:
    if (!ret) {
        free(pool->session_id);
        pool->session_id = NULL;
        free(pool->nonce);
        pool->nonce = NULL;
    }

    if (req)
        json_decref(req);
    if (resp)
        json_decref(resp);
    return ret;
}

bool stratum_init_connection(struct pool *pool) {
    jsonrpc_request *req;
    char *session_id = NULL;
    int nonce = 0;
    bool success = false;
    int retry = 0;

    while (retry < 2) {
        req = jsonrpc_request_new("mining.subscribe", NULL, NULL);
        if (!req)
            return false;

        json_t *result = NULL;
        if (!jsonrpc_call(req, pool->stratum_url, &result)) {
            applog(LOG_ERR, "Stratum subscription request failed for pool %d", pool->idx);
            jsonrpc_request_free(req);
            return false;
        }

        if (!result || !json_is_array(result)) {
            applog(LOG_ERR, "Invalid response from Stratum server for pool %d", pool->idx);
            jsonrpc_request_free(req);
            json_decref(result);
            return false;
        }

        json_t *session_id_json = json_array_get(result, 0);
        json_t *extradata = json_array_get(result, 1);

        if (!session_id_json || !json_is_string(session_id_json)) {
            applog(LOG_ERR, "Failed to extract session ID from Stratum response for pool %d", pool->idx);
            jsonrpc_request_free(req);
            json_decref(result);
            return false;
        }

        session_id = strdup(json_string_value(session_id_json));
        if (!session_id) {
            applog(LOG_ERR, "Memory allocation failure for session ID");
            jsonrpc_request_free(req);
            json_decref(result);
            return false;
        }

        if (extradata && json_is_string(extradata)) {
            char *extradata_str = strdup(json_string_value(extradata));
            if (!extradata_str) {
                applog(LOG_ERR, "Memory allocation failure for extradata");
                jsonrpc_request_free(req);
                json_decref(result);
                free(session_id);
                return false;
            }
            pool->extradata = extradata_str;
        }

        jsonrpc_request_free(req);
        json_decref(result);

        if (retry == 0) {
            pool->session_id = session_id;
        } else {
            free(pool->session_id);
            pool->session_id = session_id;
        }

        applog(LOG_INFO, "Stratum session established with pool %d", pool->idx);
        success = true;
        break;
    }

    if (!success)
        applog(LOG_ERR, "Failed to establish Stratum connection after retries for pool %d", pool->idx);

    return success;
}

bool stratum_init_connection(struct pool *pool) {
    json_t *subscription, *resp;
    json_error_t err;
    char *json_str;
    char *session_id = NULL;
    char *nonce = NULL;
    bool retry = false;
    bool success = false;

    do {
        subscription = json_object();
        if (!subscription)
            goto out;

        json_object_set_new(subscription, "method", json_string("mining.subscribe"));
        json_object_set_new(subscription, "params", json_array());
        json_object_set_new(subscription, "id", json_integer(1));

        json_str = json_dumps(subscription, JSON_COMPACT);
        if (!json_str)
            goto out;

        if (stratum_send(pool, json_str, strlen(json_str)) < 0)
            goto out;

        resp = json_loads(pool->stratum_response, JSON_DISABLE_EOF_CHECK, &err);
        if (!resp)
            goto out;

        if (!json_is_object(resp))
            goto out;

        if (json_object_get(resp, "error")) {
            applog(LOG_NOTICE, "Stratum error: %s", json_string_value(json_object_get(resp, "error")));
            goto out;
        }

        session_id = json_string_value(json_object_get(resp, "result"));
        if (!session_id)
            goto out;

        pool->session_id = strdup(session_id);

        if (!pool->session_id)
            goto out;

        success = true;

    } while (retry);

out:
    if (subscription)
        json_decref(subscription);
    if (json_str)
        free(json_str);
    if (resp)
        json_decref(resp);
    return success;
}
